module.exports=function createTalhaRunnerRuntime(ctx){
const app=ctx.app,ScriptLanguage=ctx.ScriptLanguage,UndoModes=ctx.UndoModes,core=ctx.core,MAX_HISTORY=20,FAVORITES_KEY="talhaRunnerV2Favorites",SEEN_KEY="talhaRunnerSeenUpdate",SKIP_KEY="talhaRunnerSkippedUpdate";let history=[],listeners=[],latest=null,timer=null;
function on(el,e,h){if(!el)return;el.addEventListener(e,h);listeners.push([el,e,h]);}function $(id){return document.getElementById(id);}function store(k,v){try{localStorage.setItem(k,v);}catch(e){}}function load(k){try{return localStorage.getItem(k)||"";}catch(e){return"";}}
function render(){const root=$(ctx.rootId||"talha-runner-root");if(!root)throw new Error("Runner host bulunamadı");root.innerHTML=`<style id="runner-style">*{box-sizing:border-box}.tr{--bg:#11151d;--surface:#1b2230;--surface2:#222b3b;--line:#344057;--text:#f5f7fb;--muted:#96a2b7;--blue:#5b8cff;--cyan:#45d4e8;--violet:#a678ff;--amber:#f2b84b;--green:#46d28c;--red:#ff6673;width:100%;height:100%;display:flex;flex-direction:column;padding:12px;gap:9px;background:linear-gradient(155deg,#10141c,#171d28 58%,#121722);color:var(--text);font-family:Arial,sans-serif}.top{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:54px;padding:9px 11px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(120deg,#202838,#1a2130)}.brand{min-width:0}.name{font-size:16px;font-weight:800;letter-spacing:.7px;white-space:nowrap}.meta{margin-top:3px;font-size:10px;color:var(--muted);white-space:nowrap}.topright{display:flex;align-items:center;gap:8px;min-width:0}.ustatus{font-size:10px;color:var(--muted);white-space:nowrap;max-width:125px;overflow:hidden;text-overflow:ellipsis}.bell{position:relative;width:34px;height:34px;flex:0 0 34px;border:1px solid #46536a;border-radius:10px;background:#273143}.bellbody{position:absolute;left:10px;top:7px;width:12px;height:14px;border:2px solid #dce6f8;border-radius:8px 8px 4px 4px}.bellbody:after{content:"";position:absolute;left:3px;bottom:-5px;width:4px;height:3px;border-radius:0 0 4px 4px;background:#dce6f8}.dot{display:none;position:absolute;right:4px;top:4px;width:7px;height:7px;border-radius:50%;background:var(--red)}.bell.unread .dot{display:block}.notice{display:none;padding:10px;border:1px solid #46536a;border-radius:11px;background:#202838}.notice.show{display:block}.ntitle{font-size:12px;font-weight:700}.nsummary{margin-top:4px;font-size:10px;line-height:1.4;color:#bdc7d8}.nbuttons{display:flex;gap:7px;margin-top:8px}.editor{flex:1 1 auto;min-height:100px;width:100%;padding:12px;border:1px solid #39465d;border-radius:12px;outline:none;resize:none;background:#0d1118;color:#f3f6fc;font:12px/1.5 Consolas,"Courier New",monospace}.editor:focus{border-color:var(--blue);box-shadow:0 0 0 1px rgba(91,140,255,.25)}button{height:34px;border:1px solid #46536a;border-radius:9px;background:#293345;color:#fff;padding:0 10px;font-size:11px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.primary{background:linear-gradient(135deg,#4778ed,#625ce8);border-color:#7999ff}.row{display:flex;gap:8px}.run{flex:1 1 auto}.clear{flex:0 0 80px}.option{display:flex;align-items:center;min-height:20px;font-size:10px;color:#b6c0d1}.option input{margin-right:5px}.status{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:30px;padding:6px 8px;border:1px solid #303b50;border-radius:9px;background:#171d27;font-size:10px}.statusmsg{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.shortcut{flex:0 0 auto;color:#758299}.tools{display:flex;gap:7px}.tools button{flex:1 1 0;min-width:0;padding:0 5px}.save{border-color:#806329;color:#ffd77c}.fav{border-color:#2d7082;color:#8ceafa}.hist{border-color:#654a8a;color:#cbb0ff}.update{border-color:#347553;color:#86efb5}.nbuttons button{flex:1;height:30px;font-size:10px}.details{border-color:#426ea9;color:#9dc5ff}.skip{border-color:#72577a;color:#d9b6e4}@media(max-width:330px){.tr{padding:8px;gap:6px}.top{padding:7px 8px}.name{font-size:14px}.ustatus{display:none}.tools{gap:4px}.tools button{font-size:9px}.meta{font-size:9px}}</style><div class="tr"><div class="top"><div class="brand"><div class="name">TALHA RUNNER</div><div class="meta" id="versionText"></div></div><div class="topright"><div class="ustatus" id="updateStatus">● Hazır</div><button class="bell" id="bellButton" title="Bildirimler"><span class="bellbody"></span><span class="dot"></span></button></div></div><div class="notice" id="notificationCard"><div class="ntitle" id="notificationTitle"></div><div class="nsummary" id="notificationSummary"></div><div class="nbuttons"><button class="details" id="detailsButton">Detaylar</button><button class="skip" id="skipButton">Bu sürümü atla</button></div></div><textarea class="editor" id="codeInput" spellcheck="false" placeholder="Yapay zekâdan aldığın InDesign kodunu buraya yapıştır..."></textarea><div class="row"><button class="primary run" id="runButton">▶ ÇALIŞTIR</button><button class="clear" id="clearButton">Temizle</button></div><label class="option"><input id="clearAfterRun" type="checkbox">Çalıştırınca kodu temizle</label><div class="status"><span class="statusmsg" id="statusText">Hazır</span><span class="shortcut">Ctrl + Enter</span></div><div class="tools"><button class="save" id="saveFavoriteButton">★ Kaydet</button><button class="fav" id="favoritesButton">★ Favoriler</button><button class="hist" id="historyButton">Geçmiş</button><button class="update" id="updateButton">Güncelle</button></div></div>`;}
function initialize(){render();const code=$("codeInput"),run=$("runButton"),clear=$("clearButton"),clearAfter=$("clearAfterRun"),status=$("statusText"),historyBtn=$("historyButton"),saveBtn=$("saveFavoriteButton"),favBtn=$("favoritesButton"),updateBtn=$("updateButton"),version=$("versionText"),updateStatus=$("updateStatus"),bell=$("bellButton"),card=$("notificationCard"),noticeTitle=$("notificationTitle"),noticeSummary=$("notificationSummary"),details=$("detailsButton"),skip=$("skipButton");
function setStatus(m){status.textContent=m;}function refresh(){version.textContent="Runtime "+core.getRuntimeVersion()+"  •  Core "+core.getCoreVersion();updateStatus.textContent="● Güncel";}refresh();function focus(){try{code.focus();}catch(e){}}function restore(){try{if(app.activeWindow&&app.activeWindow.activate)app.activeWindow.activate();}catch(e){}}
function addHistory(c){if(c&&history[0]!==c){history.unshift(c);if(history.length>MAX_HISTORY)history.pop();}}function runCode(){const c=code.value;if(!c||!c.replace(/\s/g,""))return setStatus("Kod alanı boş");setStatus("Çalıştırılıyor…");try{app.doScript(c,ScriptLanguage.JAVASCRIPT,undefined,UndoModes.ENTIRE_SCRIPT,"Talha Runner V2");addHistory(c);setStatus("✓ Tamamlandı");if(clearAfter.checked)code.value="";}catch(e){setStatus("✕ "+(e&&e.message?e.message:String(e)));}finally{restore();}}
function loadFav(){try{const a=JSON.parse(localStorage.getItem(FAVORITES_KEY)||"[]");return Array.isArray(a)?a:[];}catch(e){return[];}}function saveFav(a){localStorage.setItem(FAVORITES_KEY,JSON.stringify(a));}function saveCurrent(){const c=code.value;if(!c||!c.replace(/\s/g,""))return setStatus("Favoriye kaydedilecek kod yok");const n=prompt("Favori adı:","");if(n===null||!String(n).trim())return;const name=String(n).trim(),a=loadFav(),i=a.findIndex(x=>String(x.name).toLocaleLowerCase()===name.toLocaleLowerCase());if(i>=0){if(!confirm("'"+a[i].name+"' zaten var. Üzerine yazılsın mı?"))return;a[i]={name,code:c};}else a.push({name,code:c});saveFav(a);setStatus("★ Favoriye kaydedildi: "+name);}
function showFav(){const a=loadFav();if(!a.length)return setStatus("Favoriler boş");let m="FAVORİLER\n\n";a.forEach((x,i)=>m+=(i+1)+". "+x.name+"\n");const s=prompt(m+"\nNumarayı yaz ve yükle:","1");if(s!==null&&/^\d+$/.test(String(s).trim())&&a[Number(s)-1]){const x=a[Number(s)-1];code.value=x.code;setStatus("★ Favoriden yüklendi: "+x.name);focus();}}
function showHistory(){if(!history.length)return setStatus("Geçmiş boş");let m="SON ÇALIŞTIRILAN KODLAR\n\n";history.forEach((x,i)=>m+=(i+1)+". "+x.replace(/[\r\n]/g," ").slice(0,55)+"\n");const s=prompt(m,"1");if(s!==null&&/^\d+$/.test(String(s).trim())&&history[Number(s)-1]!==undefined){code.value=history[Number(s)-1];focus();}}
function renderNotice(info){latest=info;if(!info.available){bell.classList.remove("unread");card.classList.remove("show");updateStatus.textContent="● Güncel";return;}if(load(SKIP_KEY)===info.version){bell.classList.remove("unread");return;}if(load(SEEN_KEY)!==info.version)bell.classList.add("unread");noticeTitle.textContent="Yeni sürüm • "+info.version;noticeSummary.textContent=info.summary||"Yeni sürüm mevcut.";updateStatus.textContent="● Güncelleme var";}
async function silentCheck(){try{renderNotice(await core.checkForUpdate());}catch(e){}}async function openBell(){try{renderNotice(await core.checkForUpdate());}catch(e){}if(!latest||!latest.available)return setStatus("Yeni bildirim yok");store(SEEN_KEY,latest.version);bell.classList.remove("unread");card.classList.toggle("show");}function showDetails(){if(!latest)return;let m=(latest.title||("TALHA RUNNER "+latest.version))+"\n\n"+(latest.summary||"");if(latest.notes&&latest.notes.length)m+="\n\n• "+latest.notes.join("\n• ");const p=core.getPreviousVersion();m+="\n\nRuntime: "+core.getRuntimeVersion()+"\nCore: "+core.getCoreVersion()+(p?"\nÖnceki: "+p:"");alert(m);}function skipVersion(){if(!latest||!latest.available)return;store(SKIP_KEY,latest.version);store(SEEN_KEY,latest.version);bell.classList.remove("unread");card.classList.remove("show");setStatus("Bu sürüm atlandı: "+latest.version);}
async function update(){setStatus("Güncelleme kontrol ediliyor…");updateBtn.disabled=true;try{const info=await core.checkForUpdate();if(!info.available){refresh();return setStatus("✓ Zaten güncel: "+core.getRuntimeVersion());}setStatus("İndiriliyor ve doğrulanıyor…");const r=await core.checkAndInstallUpdate();if(r.updated){store(SEEN_KEY,r.version);store(SKIP_KEY,"");setTimeout(()=>{const v=$("versionText"),s=$("statusText"),u=$("updateStatus");if(v)v.textContent="Runtime "+core.getRuntimeVersion()+"  •  Core "+core.getCoreVersion();if(s)s.textContent="✓ Güncellendi: "+r.version;if(u)u.textContent="● Güncel";},50);}}catch(e){setStatus("✕ Güncelleme başarısız: "+(e.message||e));}finally{if($("updateButton"))$("updateButton").disabled=false;}}
on(run,"click",runCode);on(clear,"click",()=>{code.value="";setStatus("Hazır");focus();});on(code,"keydown",e=>{if(e.ctrlKey&&e.key==="Enter"){e.preventDefault();runCode();}});on(saveBtn,"click",saveCurrent);on(favBtn,"click",showFav);on(historyBtn,"click",showHistory);on(updateBtn,"click",update);on(bell,"click",openBell);on(details,"click",showDetails);on(skip,"click",skipVersion);setStatus("Hazır");setTimeout(silentCheck,900);timer=setInterval(silentCheck,300000);}
function dispose(){if(timer){clearInterval(timer);timer=null;}listeners.forEach(x=>{try{x[0].removeEventListener(x[1],x[2]);}catch(e){}});listeners=[];const root=$(ctx.rootId||"talha-runner-root");if(root)root.innerHTML="";}
return{initialize,dispose};};
